export function evaluate({ inputs, time }) {
  const u = inputs.launchSpeed, g = inputs.gravity, m = inputs.mass;
  const T = 2 * u / g, ta = u / g;
  const t = sdk.clamp(time, 0, T);
  const y = u * t - g * t * t / 2;
  const v = u - g * t;
  const H = u * u / (2 * g);
  const F = m * g;
  let st = 'Rising';
  if (t <= 0) st = 'Ready to toss';
  else if (t >= T - 1e-9) st = 'Back at launch height';
  else if (Math.abs(t - ta) < 0.005) st = 'At the top';
  else if (t > ta) st = 'Falling';
  const o = [];
  o.push(...sdk.panel({ id: 'lane.motion', x: 10, y: 34, w: 300, h: 376, title: 'The motion', state: st }));
  o.push(...sdk.panel({ id: 'lane.graph', x: 330, y: 34, w: 300, h: 376, title: 'Velocity over time', state: 'v = u - g t' }));
  o.push(sdk.axis('axis.h', { x: 70, y: 380, length: 300 - 60 + 0 > 0 ? 300 : 300, orientation: 'y', min: 0, max: 2.2, ticks: [0, 1, 2], label: 'Height', unit: 'm' }));
  const py = 380 - (y / 2.2) * 300 * 1;
  const sc = 8;
  o.push(sdk.circle('ball.toss', 130, py, 24, {}));
  o.push(...sdk.vector('vec.v', { x: 130, y: py }, { value: v, direction: 'up' }, { scale: 8, label: 'v' }));
  o.push(...sdk.vector('vec.a', { x: 160, y: py }, { value: -g, direction: 'up' }, { scale: 6, label: 'a' }));
  o.push(sdk.callout(190, 200, ['v = ' + sdk.format(v, 2) + ' m/s', 'a = ' + sdk.format(-g, 1) + ' m/s^2', 'Fg = ' + sdk.format(F, 1) + ' N'], { id: 'callout.toss' }));
  const n = 24, pts = [], cont = [];
  for (let i = 0; i < n; i++) {
    const x = 1.8 * i / (n - 1);
    const vv = sdk.clamp(u - g * x, -5.5, 5.5);
    (x <= t ? pts : cont).push({ x, y: vv });
  }
  pts.push({ x: t, y: v });
  const series = [{ label: 'v up to now', kind: 'line', points: pts }];
  if (cont.length > 1) series.push({ label: 'continuation', kind: 'line', points: cont });
  o.push(sdk.plot('plot.vt', { x: 340, y: 64, w: 280, h: 300, axes: { x: { label: 'Time', min: 0, max: 1.8, unit: 's' }, y: { label: 'Velocity', min: -5.5, max: 5.5, unit: 'm/s' } }, series }));
  o.push(sdk.text('plot.vt.note', 480, 398, 'slope a = -g', { align: 'middle' }));
  return { frame: { width: 640, height: 420, objects: o, readouts: [{ id: 'velocity', value: v }, { id: 'acceleration', value: -g }, { id: 'force', value: F }, { id: 'motionState', value: st }] }, quantities: { launchSpeed: u, gravity: g, mass: m, apexTime: ta, apexHeight: H, height: y, velocity: v, acceleration: -g, force: F, motionState: 0 } };
}
